// Spring Boot REST controller handling order creation
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        // Backend validates inventory before creating order
        if (!orderService.isInStock(request.productId(), request.quantity())) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).build();
        }

        var order = orderService.createOrder(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(order);
    }
}

record OrderRequest(Long productId, int quantity, Long customerId) {}

// Java catches type errors before code runs
public class PaymentService {
    public BigDecimal calculateTotal(List<OrderItem> items) {
        return items.stream()
            .map(OrderItem::price)  // Compile error if price() returns wrong type
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

record OrderItem(String name, BigDecimal price) {}

