// Backend thinks about state consistency, not how it looks
@Service
public class AccountService {
    private final AccountRepository accountRepo;

    @Transactional  // Backend ensures atomic operations
    public void transferFunds(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId)
            .orElseThrow(() -> new AccountNotFoundException(fromId));
        var toAccount = accountRepo.findById(toId)
            .orElseThrow(() -> new AccountNotFoundException(toId));

        // Business logic: prevent negative balance
        if (fromAccount.balance().compareTo(amount) < 0) {
            throw new InsufficientFundsException();
        }

        fromAccount.debit(amount);  // State changes must be consistent
        toAccount.credit(amount);   // Both succeed or both fail
    }
}

// Challenge: prevent lost updates when multiple users edit same entity
@Entity
public class Product {
    @Id
    private Long id;

    private String name;
    private BigDecimal price;

    @Version  // Optimistic locking: JPA checks version on update
    private Long version;
}

@Service
public class ProductService {
    private final ProductRepository productRepo;

    public void updatePrice(Long productId, BigDecimal newPrice) {
        var product = productRepo.findById(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));

        product.setPrice(newPrice);
        // If another transaction modified this product, JPA throws OptimisticLockException
        productRepo.save(product);  // Version check happens here
    }
}

